#!/bin/sh
# Tier 1 wrapper for the Cursor IDE, profile ${PROFILE_NAME}.
#
# --user-data-dir and --extensions-dir both work on the installed build
# (measured 2026-09-18): the probe dir received User/, logs/, machineid and
# CachedProfilesData while the default config dir kept its mtime.
#
# Note which binary: /usr/share/cursor/cursor is the GUI entry point and hangs
# on --help; /usr/share/cursor/bin/cursor is the CLI. This wrapper is the CLI
# path. The .desktop launcher uses the GUI one.
#
# Generated by devkit; edits are lost on `devkit profile sync`.
set -eu
DEVKIT_PROFILE="${PROFILE_NAME}"
export DEVKIT_PROFILE
DEVKIT_PROFILE_HOME="${PROFILE_HARNESS_DIR}"
export DEVKIT_PROFILE_HOME
AGENTS_HOME="${PROFILE_AGENTS_HOME}"
export AGENTS_HOME
PATH="${PROFILE_BIN_DIR}:${PATH}"
export PATH
# graft writes .gitignore and .ignore into every repo it builds in; the kit
# ships those patterns in the global git ignore instead.
GRAFT_NO_GITIGNORE=1
GRAFT_NO_IGNORE=1
export GRAFT_NO_GITIGNORE GRAFT_NO_IGNORE
exec "${PROFILE_CURSOR_CLI}" \
  --user-data-dir "${PROFILE_CONFIG_DIR}" \
  --extensions-dir "${PROFILE_DATA_DIR}/extensions" \
  "$@"
